  return(x^2);
}

pair A = (1,1), O = (0,3/2);

draw(Circle(O,sqrt(5)/2));
draw(graph(func,-1.5,1.5));
draw((-1.5,0)--(1.5,0));
draw((0,-0.5)--(0,3));

dot("$(a,a^2)$", A, SE);
dot("$(-a,a^2)$", (-1,1), SW);
